from pathlib import Path

main_path = Path('fida-field/app/src/main/java/com/fidalix/fidafield/MainActivity.java')
cloud_path = Path('fida-field/app/src/main/java/com/fidalix/fidafield/CloudSyncFoundation.java')
gradle_path = Path('fida-field/app/build.gradle')


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f'0.9.32 patch failed: {label} pattern not found')
    return text.replace(old, new, 1)

