old_checklist = '''    private void showServiceChecklist(EditText work){\n        String[] types={"Preventive maintenance","Corrective maintenance","Installation / commissioning","Inspection / site survey"};\n        new MaterialAlertDialogBuilder(this).setTitle("Choose service checklist").setItems(types,(d,which)->{\n            if(which==0)showServiceChecklistItems("Preventive maintenance",new String[]{"Visual condition inspected","Connections and cabling checked","Equipment cleaned or housekeeping completed","Operational test completed","Alarms and indicators checked","Maintenance findings recorded"},work);\n            else if(which==1)showServiceChecklistItems("Corrective maintenance",new String[]{"Fault symptoms verified","Fault source isolated","Repair or replacement completed","Connections restored and secured","Operational test completed","Final operating condition verified"},work);\n            else if(which==2)showServiceChecklistItems("Installation / commissioning",new String[]{"Equipment installed or mounted","Power and cabling connected","Configuration completed","Network or service connectivity tested","Functional test completed","Labelling or handover completed"},work);\n            else showServiceChecklistItems("Inspection / site survey",new String[]{"Physical condition inspected","Power and environment checked","Cabling and connections inspected","Configuration or status reviewed","Findings documented","Recommendations recorded"},work);\n        }).setNegativeButton("Cancel",null).show();\n    }\n'''
new_checklist = '''    private void showServiceChecklist(EditText work){\n        JSONArray templates=currentServiceTypes();if(templates.length()==0){toast("No service types are configured");return;}String[] labels=new String[templates.length()];for(int i=0;i<templates.length();i++){JSONObject o=templates.optJSONObject(i);labels[i]=o==null?"Service type":o.optString("name","Service type");}\n        new MaterialAlertDialogBuilder(this).setTitle("Choose service checklist").setItems(labels,(d,which)->{JSONObject o=templates.optJSONObject(which);if(o==null)return;JSONArray a=o.optJSONArray("items");ArrayList<String> items=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++){String v=a.optString(i,"").trim();if(!v.isEmpty())items.add(v);}if(items.isEmpty()){toast("This service type has no checklist actions");return;}showServiceChecklistItems(o.optString("name","Service type"),items.toArray(new String[0]),work);}).setNegativeButton("Cancel",null).show();\n    }\n'''
s = replace_once(s, old_checklist, new_checklist, 'dynamic service checklist')

anchor = '    private void showServiceChecklist(EditText work){\n'
helpers = '''    private JSONArray defaultServiceTypes(){\n        try{return new JSONArray()\n            .put(new JSONObject().put("template_key","preventive").put("name","Preventive maintenance").put("items",new JSONArray(new String[]{"Visual condition inspected","Connections and cabling checked","Equipment cleaned or housekeeping completed","Operational test completed","Alarms and indicators checked","Maintenance findings recorded"})))\n            .put(new JSONObject().put("template_key","corrective").put("name","Corrective maintenance").put("items",new JSONArray(new String[]{"Fault symptoms verified","Fault source isolated","Repair or replacement completed","Connections restored and secured","Operational test completed","Final operating condition verified"})))\n            .put(new JSONObject().put("template_key","installation").put("name","Installation / commissioning").put("items",new JSONArray(new String[]{"Equipment installed or mounted","Power and cabling connected","Configuration completed","Network or service connectivity tested","Functional test completed","Labelling or handover completed"})))\n            .put(new JSONObject().put("template_key","inspection").put("name","Inspection / site survey").put("items",new JSONArray(new String[]{"Physical condition inspected","Power and environment checked","Cabling and connections inspected","Configuration or status reviewed","Findings documented","Recommendations recorded"})));}catch(Exception e){return new JSONArray();}\n    }\n\n    private String serviceTypesWorkspaceId(){return accountTeam!=null&&accountTeam.hasCloudWorkspace()?accountTeam.workspaceId():"local";}\n    private JSONArray currentServiceTypes(){JSONArray cached=cloudSync==null?new JSONArray():cloudSync.cachedServiceTypes(serviceTypesWorkspaceId());return cached.length()>0?cached:defaultServiceTypes();}\n\n    private String serviceItemsText(JSONArray items){StringBuilder b=new StringBuilder();if(items!=null)for(int i=0;i<items.length();i++){String v=items.optString(i,"").trim();if(v.isEmpty())continue;if(b.length()>0)b.append("\\n");b.append(v);}return b.toString();}\n\n    private JSONArray parseServiceItems(String text){JSONArray a=new JSONArray();java.util.HashSet<String> seen=new java.util.LinkedHashSet<>();for(String line:(text==null?"":text).split("\\r?\\n")){String v=line.trim();if(!v.isEmpty())seen.add(v);}for(String v:seen)a.put(v);return a;}\n\n    private void persistServiceTypes(JSONArray types){\n        String wid=serviceTypesWorkspaceId();cloudSync.cacheServiceTypes(wid,types,true);toast("Service types saved");\n        if(accountTeam!=null&&accountTeam.hasCloudWorkspace()&&cloudSync.signedIn()&&canManageWorkspaceSettings()){new Thread(()->{try{cloudSync.syncServiceTypes(accountTeam.workspaceId(),true);runOnUiThread(()->toast("Service types synced to workspace"));}catch(Exception e){runOnUiThread(()->toast("Saved locally · cloud sync pending"));}}).start();}\n    }\n\n    private void showServiceTypesSettings(){\n        if(!requireWorkspaceManager("Service types"))return;setHeader("Service types","Workspace checklists");clear();LinearLayout b=body(page());MaterialButton back=outlineButton("← Settings");back.setOnClickListener(v->showSettings());b.addView(back);b.addView(paragraph("Edit the service types shown in the job checklist. Put each checklist action on its own line. Workspace changes sync for Owner/Admin and remain available offline."));\n        JSONArray types=currentServiceTypes();b.addView(section("Configured service types"));for(int i=0;i<types.length();i++){JSONObject o=types.optJSONObject(i);if(o==null)continue;final int index=i;JSONArray items=o.optJSONArray("items");MaterialCardView c=rowCard(o.optString("name","Service type"),(items==null?0:items.length())+" checklist action(s)","Edit");c.setOnClickListener(v->editServiceType(index));b.addView(c);}\n        MaterialButton add=button("+ Add service type");add.setOnClickListener(v->editServiceType(-1));b.addView(add);MaterialButton restore=outlineButton("Restore default service types");restore.setOnClickListener(v->new MaterialAlertDialogBuilder(this).setTitle("Restore defaults?").setMessage("This replaces the current service types and checklist actions with the four Fida Field defaults.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(d,w)->{persistServiceTypes(defaultServiceTypes());showServiceTypesSettings();}).show());b.addView(restore);\n    }\n\n    private void editServiceType(int index){\n        JSONArray types=currentServiceTypes();JSONObject existing=index>=0?types.optJSONObject(index):null;LinearLayout f=form();EditText name=input("Service type name *",existing==null?"":existing.optString("name",""));EditText items=multi("Checklist actions · one per line",existing==null?"":serviceItemsText(existing.optJSONArray("items")));items.setMinLines(6);f.addView(name);f.addView(items);\n        if(existing!=null&&types.length()>1){MaterialButton remove=outlineButton("Delete service type");remove.setOnClickListener(v->new MaterialAlertDialogBuilder(this).setTitle("Delete service type?").setMessage(existing.optString("name","Service type")+" will no longer appear in the checklist. Existing job reports are not changed.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{types.remove(index);persistServiceTypes(types);showServiceTypesSettings();}).show());f.addView(remove);}\n        AlertDialog dialog=new MaterialAlertDialogBuilder(this).setTitle(existing==null?"Add service type":"Edit service type").setView(scrollForm(f)).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String n=val(name);JSONArray list=parseServiceItems(val(items));if(n.isEmpty()){name.setError("Required");return;}if(list.length()==0){items.setError("Add at least one checklist action");return;}try{JSONObject o=existing==null?new JSONObject().put("template_key","custom-"+java.util.UUID.randomUUID()):new JSONObject(existing.toString());o.put("name",n).put("items",list);if(index>=0)types.put(index,o);else types.put(o);persistServiceTypes(types);dialog.dismiss();showServiceTypesSettings();}catch(Exception e){error("Could not save service type",e);}}));dialog.show();\n    }\n\n'''
s = replace_once(s, anchor, helpers + anchor, 'service type editor helpers')

