reset_methods = '''    private void confirmResetAllAppData(){\n        if(!requireWorkspaceManager("Reset all app data"))return;LinearLayout f=form();f.addView(paragraph("This permanently removes all local customers, sites, assets, jobs, photos, signatures, settings, cached service types and cloud sign-in from this device. Supabase workspace data is NOT deleted. Type RESET to continue."));EditText confirm=input("Type RESET","");f.addView(confirm);AlertDialog dialog=new MaterialAlertDialogBuilder(this).setTitle("Reset all app data?").setView(scrollForm(f)).setNegativeButton("Cancel",null).setPositiveButton("Reset",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(!"RESET".equals(val(confirm))){confirm.setError("Type RESET exactly");return;}dialog.dismiss();performLocalFactoryReset();}));dialog.show();\n    }\n\n    private void performLocalFactoryReset(){\n        try{\n            try{JSONObject snap=db.exportJson();JSONArray photos=snap.optJSONArray("job_photos");if(photos!=null)for(int i=0;i<photos.length();i++){String u=photos.optJSONObject(i)==null?"":photos.optJSONObject(i).optString("uri","");if(u.startsWith("content://"))try{getContentResolver().delete(Uri.parse(u),null,null);}catch(Exception ignored){}}}catch(Exception ignored){}\n            try{WorkManager.getInstance(this).cancelAllWork();}catch(Exception ignored){}if(billingManager!=null)billingManager.stop();if(db!=null)db.close();deleteDatabase(AppDatabase.DB_NAME);deleteTree(getFilesDir());deleteTree(getCacheDir());prefs.edit().clear().commit();\n            Intent launch=getPackageManager().getLaunchIntentForPackage(getPackageName());if(launch!=null){launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(launch);}finish();\n        }catch(Exception e){error("Could not reset app data",e);}\n    }\n\n    private void deleteTree(File f){if(f==null||!f.exists())return;if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File c:children)deleteTree(c);}try{f.delete();}catch(Exception ignored){}}\n\n'''
s = replace_once(s, anchor, reset_methods + anchor, 'factory reset methods')
